import java.util.*;

class Solution {
  public int trapRainWater(int[][] heightMap) {
    int m = heightMap.length, n = heightMap[0].length;
    if (m < 3 || n < 3) return 0;
    PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
    boolean[][] seen = new boolean[m][n];
    for (int i = 0; i < m; i++) {
      add(pq, seen, heightMap, i, 0);
      add(pq, seen, heightMap, i, n - 1);
    }
    for (int j = 1; j < n - 1; j++) {
      add(pq, seen, heightMap, 0, j);
      add(pq, seen, heightMap, m - 1, j);
    }
    int water = 0;
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!pq.isEmpty()) {
      int[] cell = pq.poll();
      for (int[] d : dirs) {
        int r = cell[1] + d[0], c = cell[2] + d[1];
        if (r < 0 || r >= m || c < 0 || c >= n || seen[r][c]) continue;
        seen[r][c] = true;
        water += Math.max(0, cell[0] - heightMap[r][c]);
        pq.offer(new int[] {Math.max(cell[0], heightMap[r][c]), r, c});
      }
    }
    return water;
  }

  private void add(PriorityQueue<int[]> pq, boolean[][] seen, int[][] h, int r, int c) {
    if (!seen[r][c]) {
      seen[r][c] = true;
      pq.offer(new int[] {h[r][c], r, c});
    }
  }
}
